import{_ as l,C as n,o as a,c as g,a5 as r,b as s,w as t,a as i,E as d,a7 as c}from"./chunks/framework.QWVCgkrI.js";const A=JSON.parse('{"title":"Gitのマージ — 共通祖先と3-way merge","description":"","frontmatter":{"title":"Gitのマージ — 共通祖先と3-way merge","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"tools","summary":"二つのブランチの先端と共通の基準から変更を統合する仕組みを、ゲーム設定の例で追い、fast-forwardと自動マージ後の不整合を区別する。","aliases":["Git merge","3-way merge","三方向マージ","merge base","マージベース","共通祖先","fast-forward","意味的な競合"],"verification":"Git公式のmerge-base・merge・ls-files仕様とPro Gitに照合し、Windowsの独立リポジトリでort・fast-forward・競合を確認（2026-11-17）"}},"headers":[],"relativePath":"tools/git-three-way-merge.md","filePath":"tools/git-three-way-merge.md"}'),m={name:"tools/git-three-way-merge.md"};function h(E,e,p,f,u,b){const o=n("Mermaid");return a(),g("div",null,[e[2]||(e[2]=r('<h1 id="gitのマージ-—-共通祖先と3-way-merge" tabindex="-1">Gitのマージ — 共通祖先と3-way merge <a class="header-anchor" href="#gitのマージ-—-共通祖先と3-way-merge" aria-label="Permalink to &quot;Gitのマージ — 共通祖先と3-way merge&quot;">​</a></h1><p>二人が同じゲームの設定を編集します。片方は選択中の装備を剣から盾に変え、もう片方は候補から盾を削除しました。どちらのブランチでも、選択中の装備は候補に含まれています。ところが、二つの変更を組み合わせると、選択中の盾が候補から消えます。Gitがどうやってこの組み合わせを作るかは、両方の先端に加えて、二人が編集を始めた時点を見ると分かります。</p><h2 id="比べるのは基準と二つの先端" tabindex="-1">比べるのは基準と二つの先端 <a class="header-anchor" href="#比べるのは基準と二つの先端" aria-label="Permalink to &quot;比べるのは基準と二つの先端&quot;">​</a></h2><p>コミットの親をたどって二つの先端の両方から到達できるコミットを、共通祖先と呼びます。共通祖先の候補から、別の共通祖先の祖先になっているものを除くと、<strong>マージベース</strong>が残ります。候補を絞る基準は履歴の親子関係です。検証例ではマージ前の <code>git merge-base main feature</code> が図のBを返しました。<a href="https://git-scm.com/docs/git-merge-base#_description" target="_blank" rel="noreferrer">git merge-baseの公式マニュアル</a></p>',4)),(a(),s(c,null,{default:t(()=>[d(o,{id:"mermaid-12",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20%E5%88%86%E5%B2%90%E3%81%97%E3%81%9F%E4%BA%8C%E3%81%A4%E3%81%AE%E3%82%B3%E3%83%9F%E3%83%83%E3%83%88%E3%81%A8%E3%83%9E%E3%83%BC%E3%82%B8%E7%B5%90%E6%9E%9C%0A%20%20%20%20accDescr%3A%20B%E3%81%8B%E3%82%89H%E3%81%A8F%E3%81%AB%E5%88%86%E5%B2%90%E3%81%99%E3%82%8B%E3%80%82H%E3%81%A8F%E3%82%92%E8%A6%AA%E3%81%A8%E3%81%97%E3%81%A6M%E3%81%8C%E4%BD%9C%E3%82%89%E3%82%8C%E3%82%8B%E3%80%82%0A%20%20%20%20b%5B%22B%20%E5%85%B1%E9%80%9A%E3%81%AE%E5%9F%BA%E6%BA%96%22%5D%20--%3E%20h%5B%22H%20main%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%0A%20%20%20%20b%20--%3E%20f%5B%22F%20feature%E3%81%AE%E5%85%88%E7%AB%AF%22%5D%0A%20%20%20%20h%20--%3E%20m%5B%22M%20%E3%83%9E%E3%83%BC%E3%82%B8%E7%B5%90%E6%9E%9C%22%5D%0A%20%20%20%20f%20--%3E%20m%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r(`<p>図の矢印は履歴の親から子へ向いています。HとFだけを見て <code>selected.txt</code> の内容が違っても、どちらが変更したかは分かりません。Bと比べると、Hが選択を <code>shield</code> に変え、Fは元の <code>sword</code> を残したことが分かります。<code>items.txt</code> では逆に、Fだけが候補を変更しています。<strong>3-way merge</strong>は、このようにB・H・Fの三つの状態を使って両側の変更を組み合わせます。分岐した両側を通常のマージコミットでつなぐと、Mは統合したtreeと、H・Fの二つの親を持ちます。<a href="https://git-scm.com/book/en/v2/Git-Branching-Basic-Branching-and-Merging#_basic_merging" target="_blank" rel="noreferrer">Pro Gitのマージの解説</a> · <a href="https://git-scm.com/docs/git-merge/2.38.0#_merge_strategies" target="_blank" rel="noreferrer">Git公式の <code>ort</code> の説明</a></p><h2 id="自動で結合できても、設定として成立するとは限らない" tabindex="-1">自動で結合できても、設定として成立するとは限らない <a class="header-anchor" href="#自動で結合できても、設定として成立するとは限らない" aria-label="Permalink to &quot;自動で結合できても、設定として成立するとは限らない&quot;">​</a></h2><p>この例のルールは「<code>selected.txt</code> の装備名が、<code>items.txt</code> に並ぶ候補のどれかと一致すること」です。表では候補を読点で区切っていますが、検証ファイルでは1行に1項目が入っています。</p><table tabindex="0"><thead><tr><th>コミット</th><th><code>items.txt</code></th><th><code>selected.txt</code></th></tr></thead><tbody><tr><td>B 共通の基準</td><td><code>sword</code>、<code>shield</code></td><td><code>sword</code></td></tr><tr><td>H <code>main</code></td><td><code>sword</code>、<code>shield</code></td><td><code>shield</code></td></tr><tr><td>F <code>feature</code></td><td><code>sword</code></td><td><code>sword</code></td></tr><tr><td>M マージ結果</td><td><code>sword</code></td><td><code>shield</code></td></tr></tbody></table><p>Git 2.39.2の <code>ort</code> を指定した <code>git merge -s ort --no-ff --no-edit feature</code> は成功しました。次の出力では、Mの短いIDの後ろにHとFのIDが並びます。設定を実際に読み取る小さな検査では、HとFはそれぞれ合格し、Mは <code>shield</code> が候補にないため失敗しました。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git show --no-patch --format=&#39;%h %p %s&#39; main</span></span>
<span class="line"><span>f123ac5 b1ba17f 062a4fe Merge branch &#39;feature&#39;</span></span></code></pre></div><p>この例では、ファイルを合わせる処理は成功し、候補と選択を合わせて評価するテストは失敗します。テキスト上は衝突しなくても、組み合わせた内容がゲームのルールを破る<strong>意味的な不整合</strong>です。設定が複数ファイルにまたがる場合、今回のようなチェックをテストに置けます。<a href="https://arxiv.org/abs/1802.06551" target="_blank" rel="noreferrer">Sousa・Dillig・Lahiriの意味的なマージ競合に関する論文</a></p><h2 id="同じ行の変更を選べないとき" tabindex="-1">同じ行の変更を選べないとき <a class="header-anchor" href="#同じ行の変更を選べないとき" aria-label="Permalink to &quot;同じ行の変更を選べないとき&quot;">​</a></h2><p>別の検証では、基準の <code>key.txt</code> にある <code>jump=Space</code> を、現在の側で <code>jump=J</code>、相手側で <code>jump=K</code> に変えました。どちらの変更を採用するかが決まらず、マージは競合で停止しました。HEADは現在側のコミットに残ります。競合中のindexを読む <code>git ls-files -u -- key.txt</code> では、このパスにステージ1・2・3の項目がありました。<a href="https://git-scm.com/docs/git-merge/2.38.0#_true_merge" target="_blank" rel="noreferrer">git mergeの競合時の動作</a> · <a href="https://git-scm.com/docs/git-ls-files/2.39.0#_output" target="_blank" rel="noreferrer">git ls-files</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ git show &#39;:1:key.txt&#39;</span></span>
<span class="line"><span>jump=Space</span></span>
<span class="line"><span>$ git show &#39;:2:key.txt&#39;</span></span>
<span class="line"><span>jump=J</span></span>
<span class="line"><span>$ git show &#39;:3:key.txt&#39;</span></span>
<span class="line"><span>jump=K</span></span></code></pre></div><p>通常のindexでは、次にコミットする版はステージ0にあります。この競合中はステージ1が基準、2が現在側、3が相手側です。どの内容を残して結合するかは解消する人が決めます。ファイルが片側に存在しない競合などでは、全ステージがそろわない場合があります。<a href="/study/tools/git-staging-index.html">Gitのステージング</a> · <a href="https://git-scm.com/docs/git-merge/2.38.0#_true_merge" target="_blank" rel="noreferrer">git mergeの競合時の動作</a></p><h2 id="fast-forwardでは先端を進める" tabindex="-1">fast-forwardでは先端を進める <a class="header-anchor" href="#fast-forwardでは先端を進める" aria-label="Permalink to &quot;fast-forwardでは先端を進める&quot;">​</a></h2><p>現在の先端が相手の先端の祖先にあたり、履歴がすでにつながっている場合は、現在のブランチ参照を相手のコミットまで進められます。これが <strong>fast-forward</strong> です。新しいマージコミットは作りません。検証用のブランチをBに置き、その子であるFを <code>git merge --ff-only feature</code> で取り込むと、更新後の先端は既存のFと同じIDになりました。HとFが分岐している図のケースでは、<code>--ff-only</code> はマージを拒否します。<a href="https://git-scm.com/docs/git-merge/2.38.0#_fast_forward_merge" target="_blank" rel="noreferrer">git mergeのfast-forwardの説明</a> · <a href="https://git-scm.com/docs/git-merge/2.38.0#_options" target="_blank" rel="noreferrer">git mergeのオプション</a></p>`,13)),(a(),s(c,null,{default:t(()=>[d(o,{id:"mermaid-106",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20accTitle%3A%20fast-forward%E3%81%A7%E5%8F%82%E7%85%A7%E3%81%AE%E5%85%88%E3%81%8C%E5%A4%89%E3%82%8F%E3%82%8B%0A%20%20%20%20accDescr%3A%20%E6%9B%B4%E6%96%B0%E5%89%8D%E3%81%AF%E3%83%96%E3%83%A9%E3%83%B3%E3%83%81%E5%8F%82%E7%85%A7%E3%81%8CB%E3%82%92%E3%80%81%E6%9B%B4%E6%96%B0%E5%BE%8C%E3%81%AF%E6%97%A2%E5%AD%98%E3%81%AEF%E3%82%92%E6%8C%87%E3%81%99%E3%80%82B%E3%81%A8F%E3%81%AE%E8%A6%AA%E5%AD%90%E9%96%A2%E4%BF%82%E3%81%AF%E3%81%9D%E3%81%AE%E3%81%BE%E3%81%BE%E3%80%82%0A%20%20%20%20a%5B%22%E6%9B%B4%E6%96%B0%E5%89%8D%20%E5%8F%82%E7%85%A7%20%E2%86%92%20B%22%5D%20--%3E%7Cfast-forward%7C%20z%5B%22%E6%9B%B4%E6%96%B0%E5%BE%8C%20%E5%8F%82%E7%85%A7%20%E2%86%92%20F%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=r('<h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><details class="details custom-block"><summary>HとFだけを比べて違う値が見つかった。どちらが変更したかを知るには？</summary><p>共通の基準Bの値も見ます。今回の <code>selected.txt</code> では、BとFが <code>sword</code>、Hが <code>shield</code> だったので、Hが変更したと分かります。</p></details><details class="details custom-block"><summary>競合なくマージが終わった。装備の設定は必ず成立する？</summary><p>候補と選択の関係は別に確かめます。今回のMでは <code>selected.txt</code> の <code>shield</code> が <code>items.txt</code> にないため、ゲーム側の条件を満たしません。</p></details><h2 id="検証範囲" tabindex="-1">検証範囲 <a class="header-anchor" href="#検証範囲" aria-label="Permalink to &quot;検証範囲&quot;">​</a></h2><p>2026年11月17日にWindowsのGit 2.39.2.windows.1で、独立したリポジトリを使いました。共通の基準が一つで、二つの先端を <code>-s ort</code> で統合した場合と、<code>--ff-only</code> で参照を進めた場合を確認しました。マージベースが複数ある履歴では、<code>ort</code> は共通の基準となるtreeを組み立てる場合があります。改名・削除を含む競合、複数のマージベース、他の戦略やカスタムのマージドライバーは未検証です。<a href="https://git-scm.com/docs/git-merge-base#_discussion" target="_blank" rel="noreferrer">git merge-base</a> · <a href="https://git-scm.com/docs/git-merge/2.38.0#_merge_strategies" target="_blank" rel="noreferrer">Git公式の <code>ort</code> の説明</a></p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/tools/git-objects.html">Gitの保存モデル</a> — commit、tree、親、ブランチ参照の役割を整理する。</li><li>統合後のtreeが同じでも、親のつながりがどう変わるかを比べる。<a href="/study/tools/git-rebase.html">Gitのrebase — コミットの再適用と履歴の書き換え</a></li><li>二つの先端を統合する場合と、片側から特定の変更を選ぶ場合の履歴を比べる。<a href="/study/tools/git-cherry-pick.html">Gitのcherry-pick — コミットではなく変更を別の履歴へ取り込む</a></li><li><a href="/study/tools/git-staging-index.html">Gitのステージング</a> — 競合のない場合にindexが次のtreeをどう作るかを読む。</li><li><a href="/study/tools/automated-testing.html">自動テストの基礎</a> — 統合した設定やコードが満たす条件を検証する。</li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://git-scm.com/docs/git-merge-base" target="_blank" rel="noreferrer">Git公式 — git merge-base</a></li><li><a href="https://git-scm.com/docs/git-merge/2.38.0" target="_blank" rel="noreferrer">Git公式 — git merge、戦略と競合時の動作</a></li><li><a href="https://git-scm.com/docs/git-ls-files/2.39.0#_output" target="_blank" rel="noreferrer">Git公式 — git ls-files</a></li><li><a href="https://git-scm.com/book/en/v2/Git-Branching-Basic-Branching-and-Merging" target="_blank" rel="noreferrer">Pro Git — Basic Branching and Merging</a></li><li><a href="https://arxiv.org/abs/1802.06551" target="_blank" rel="noreferrer">Sousa・Dillig・Lahiri — Verifying Semantic Conflict-Freedom in Three-Way Program Merges</a></li></ul>',9))])}const B=l(m,[["render",h]]);export{A as __pageData,B as default};
